// ---------------------------------------------------------------------------
//  Line of sight: can a bullet get from shooter to target without crossing a box?
//
//  Y reported by the Unity client is the FEET position (transform.position.y of the
//  CharacterController). The server only knows the last reported positions (network lag),
//  so it is deliberately LENIENT: a hit is rejected only if every ray between a small cloud of
//  sample points around both players is blocked. Walls are never shot through; peeking round a
//  corner is not punished.
// ---------------------------------------------------------------------------
const LATERAL = 0.8;                                    // metres of lag tolerance
const OFFS = [[0, 0], [LATERAL, 0], [-LATERAL, 0], [0, LATERAL], [0, -LATERAL]];
const SHOOTER_H = [1.7, 1.2, 0.8];                      // eye: standing, crouching, mid-jump landing
const TARGET_H = [1.6, 1.15, 0.7, 0.3];                 // head, chest, hips, legs
const MIN_Y = 0.2;                                      // floor is y = 0

function clip(o, d, lo, hi, r) {
  if (Math.abs(d) < 1e-9) return o >= lo && o <= hi;
  let ta = (lo - o) / d, tb = (hi - o) / d;
  if (ta > tb) { const s = ta; ta = tb; tb = s; }
  if (ta > r[0]) r[0] = ta;
  if (tb < r[1]) r[1] = tb;
  return r[0] <= r[1];
}

function segmentBlocked(ax, ay, az, bx, by, bz, boxes) {
  const dx = bx - ax, dy = by - ay, dz = bz - az;
  const r = [0, 1];
  for (let i = 0; i < boxes.length; i++) {
    const b = boxes[i];
    r[0] = 0; r[1] = 1;
    if (clip(ax, dx, b[0], b[3], r) && clip(ay, dy, b[1], b[4], r) && clip(az, dz, b[2], b[5], r)) return true;
  }
  return false;
}

function hasLineOfSight(a, b, boxes) {
  if (!boxes || boxes.length === 0) return true;
  for (const ha of SHOOTER_H) for (const hb of TARGET_H) {
    // never sample below the floor: a ray under the floor would slip beneath every wall
    const ay = Math.max(MIN_Y, a.y + ha), by = Math.max(MIN_Y, b.y + hb);
    for (const [oax, oaz] of OFFS) for (const [obx, obz] of OFFS)
      if (!segmentBlocked(a.x + oax, ay, a.z + oaz, b.x + obx, by, b.z + obz, boxes)) return true;
  }
  return false;
}

module.exports = { MAPS, DEFAULT_MAP, hasLineOfSight, segmentBlocked };

